// HasEsaSite applies the HasEdge predicate on the "esa_site" edge.
func HasEsaSite() predicate.EsaSiteRecord {
	return predicate.EsaSiteRecord(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, EsaSiteTable, EsaSiteColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEsaSiteWith applies the HasEdge predicate on the "esa_site" edge with a given conditions (other predicates).
func HasEsaSiteWith(preds ...predicate.EsaSite) predicate.EsaSiteRecord {
	return predicate.EsaSiteRecord(func(s *sql.Selector) {
		step := newEsaSiteStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EsaSiteRecord) predicate.EsaSiteRecord {
	return predicate.EsaSiteRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EsaSiteRecord) predicate.EsaSiteRecord {
	return predicate.EsaSiteRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EsaSiteRecord) predicate.EsaSiteRecord {
	return predicate.EsaSiteRecord(sql.NotPredicates(p))
}
